import { connection } from 'next/server'
import { getProjectDetails } from '@/lib/data'

export default async function ProjectPage({ params }: PageProps<'/projects/[slug]'>) {
  const { slug } = await params
  // Load details only after navigation, outside the prefetched title and loading state.
  await connection()
  const details = await getProjectDetails(slug)

  return (
    <>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </>
  )
}
import { getProjectTitle } from '@/lib/data'

export default async function ProjectLayout({
  children,
  params,
}: LayoutProps<'/projects/[slug]'>) {
  const { slug } = await params
  const title = await getProjectTitle(slug)

  return (
    <main>
      <h1>{title}</h1>
      {children}
    </main>
  )
}
export default function Loading() {
  return <p>Loading project details...</p>
}
